CREATE OR REPLACE FUNCTION public.assign_card_slot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  next_slot smallint;
begin
  if tg_op = 'UPDATE' then
    new.card_slot = old.card_slot;
    return new;
  end if;

  if new.user_id is null then
    new.card_slot = null;
    return new;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('public.cards.card_slot:' || new.user_id::text, 0)
  );

  if new.card_slot is not null then
    if exists (
      select 1
      from public.cards
      where user_id = new.user_id
        and card_slot = new.card_slot
    ) then
      raise exception 'CARD_SLOT_ALREADY_OCCUPIED: requested card slot is no longer available';
    end if;

    return new;
  end if;

  select slot
  into next_slot
  from generate_series(1, 3) as slot
  where not exists (
    select 1
    from public.cards
    where user_id = new.user_id
      and card_slot = slot
  )
  order by slot asc
  limit 1;

  if next_slot is null then
    raise exception 'CARD_SLOT_LIMIT_REACHED: users can have at most three cards';
  end if;

  new.card_slot = next_slot;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_card_media_session(p_owner uuid, p_session uuid, p_card uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare s public.card_media_sessions; c public.cards; a public.card_media_assets;
  ref text; expected text; n integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('public.cards.card_slot:' || p_owner::text,0));
  select * into s from public.card_media_sessions where id=p_session for update;
  if not found or s.owner_user_id is distinct from p_owner
     or not public.card_media_owner_exists(p_owner) then raise exception 'MEDIA_SESSION_UNAVAILABLE'; end if;
  select * into c from public.cards where id=p_card and user_id=p_owner for update;
  if not found or c.template_id is distinct from s.template_id then raise exception 'MEDIA_CARD_UNAVAILABLE'; end if;
  if s.state='attached' and s.card_id=p_card then return 'already_attached'; end if;
  if s.state <> 'pending' or s.expires_at <= now() or (s.card_id is not null and s.card_id <> p_card) then
    raise exception 'MEDIA_SESSION_UNAVAILABLE';
  end if;
  for a in select * from public.card_media_assets where session_id=p_session order by id for update loop
    ref := 'card-media:' || a.id::text;
    expected := case a.kind when 'profile' then c.profile_image_url when 'logo' then c.company_logo_url
      else c.custom_fields->>'company_banner_url' end;
    if expected = ref then
      if a.state <> 'ready' then raise exception 'MEDIA_ASSET_NOT_READY'; end if;
      update public.card_media_assets set state='attached' where id=a.id;
      n := n + 1;
    end if;
  end loop;
  if n=0 then raise exception 'NO_MEDIA_REFERENCES_TO_ATTACH'; end if;
  update public.card_media_sessions set state='attached',card_id=p_card where id=p_session;
  return 'attached';
end;
$function$

CREATE OR REPLACE FUNCTION public.card_media_cleanup_candidates(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare result jsonb;
begin
  perform public.check_card_media_cleanup_boundary();
  if p_limit is null or p_limit < 1 or p_limit > 50 then raise exception 'MEDIA_CLEANUP_BATCH_INVALID'; end if;
  select coalesce(jsonb_agg(id order by cleanup_after,id),'[]'::jsonb) into result from (
    select id,cleanup_after from public.card_media_assets
    where cleanup_after <= now() and (cleanup_lease_until is null or cleanup_lease_until <= now())
    order by cleanup_after,id limit p_limit
  ) candidates;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.check_card_media_cleanup_boundary()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare r record; p text; c oid := 'public.cards'::regclass; sig text; t oid;
begin
  if not (select relrowsecurity from pg_class where oid=c) then
    raise exception 'MEDIA_CLEANUP_CARDS_RLS_REQUIRED';
  end if;
  foreach p in array array['SELECT','INSERT','UPDATE','DELETE'] loop
    if not has_table_privilege('service_role',c,p) then raise exception 'MEDIA_CLEANUP_SERVICE_ACCESS_REQUIRED'; end if;
  end loop;
  foreach t in array array['public.card_media_assets'::regclass::oid,'public.card_media_sessions'::regclass::oid] loop
    if not (select relrowsecurity from pg_class where oid=t) then raise exception 'MEDIA_CLEANUP_REGISTRY_RLS_REQUIRED'; end if;
    foreach p in array array['SELECT','INSERT','UPDATE','DELETE'] loop
      if not has_table_privilege('service_role',t,p) then raise exception 'MEDIA_CLEANUP_REGISTRY_ACCESS_REQUIRED'; end if;
    end loop;
  end loop;
  -- Conservative membership closure also covers SET ROLE paths, not just INHERIT.
  for r in select oid,rolsuper,rolcreaterole from pg_roles where
    oid in ('authenticated'::regrole,'anon'::regrole)
    or pg_has_role('authenticated',oid,'MEMBER') or pg_has_role('anon',oid,'MEMBER') loop
    if r.rolsuper or r.rolcreaterole or r.oid=(select relowner from pg_class where oid=c) then
      raise exception 'MEDIA_CLEANUP_PRIVILEGED_BROWSER_ROLE';
    end if;
    foreach p in array array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] loop
      if has_table_privilege(r.oid,c,p) then raise exception 'MEDIA_CLEANUP_REQUIRES_CARDS_HARDENING'; end if;
    end loop;
    if current_setting('server_version_num')::integer >= 170000 then
      if has_table_privilege(r.oid,c,'MAINTAIN') then raise exception 'MEDIA_CLEANUP_REQUIRES_CARDS_HARDENING'; end if;
    end if;
    foreach p in array array['INSERT','UPDATE','REFERENCES'] loop
      if has_any_column_privilege(r.oid,c,p) then raise exception 'MEDIA_CLEANUP_REQUIRES_COLUMN_HARDENING'; end if;
    end loop;
    foreach t in array array['public.card_media_assets'::regclass::oid,'public.card_media_sessions'::regclass::oid] loop
      if r.oid=(select relowner from pg_class where oid=t) then raise exception 'MEDIA_CLEANUP_REGISTRY_OWNER_PATH'; end if;
      foreach p in array array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] loop
        if has_table_privilege(r.oid,t,p) then raise exception 'MEDIA_CLEANUP_REGISTRY_BROWSER_ACCESS'; end if;
      end loop;
      foreach p in array array['SELECT','INSERT','UPDATE','REFERENCES'] loop
        if has_any_column_privilege(r.oid,t,p) then raise exception 'MEDIA_CLEANUP_REGISTRY_COLUMN_ACCESS'; end if;
      end loop;
    end loop;
    foreach sig in array array[
      'public.finalize_client_card_media(uuid,uuid,text,uuid,smallint,jsonb,jsonb,text)',
      'public.attach_card_media_session(uuid,uuid,uuid)',
      'public.reserve_card_media_asset(uuid,uuid,text,text,text,integer)',
      'public.mark_card_media_ready(uuid,uuid,uuid)',
      'public.retire_card_media_asset(uuid)', 'public.claim_card_media_cleanup(uuid)',
      'public.create_client_card_atomic(uuid,smallint,jsonb)',
      'public.get_client_card_edit_snapshot(uuid,uuid)', 'public.card_media_owner_exists(uuid)'
    ] loop
      if to_regprocedure(sig) is null then raise exception 'MEDIA_CLEANUP_RPC_MISSING'; end if;
      if has_function_privilege(r.oid,to_regprocedure(sig),'EXECUTE')
        or not has_function_privilege('service_role',to_regprocedure(sig),'EXECUTE') then
        raise exception 'MEDIA_CLEANUP_RPC_PERMISSIONS';
      end if;
    end loop;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.claim_card_media_cleanup(p_asset uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare s public.card_media_sessions; a public.card_media_assets; sid uuid; ref text;
begin
  select session_id into sid from public.card_media_assets where id=p_asset;
  if not found then return 'not_found'; end if;
  select * into s from public.card_media_sessions where id=sid for update;
  select * into a from public.card_media_assets where id=p_asset for update;
  if a.state='deleted' then return 'deleted'; end if;
  if a.state='attached' then return 'attached'; end if;
  if a.cleanup_after > now() then return 'not_due'; end if;
  ref := 'card-media:' || a.id::text;
  if exists(select 1 from public.cards where profile_image_url=ref or company_logo_url=ref
      or custom_fields->>'company_banner_url'=ref) then return 'referenced'; end if;
  update public.card_media_assets set state='deleting' where id=p_asset;
  if s.state = 'pending'
    and (
      s.expires_at <= now()
      or not public.card_media_owner_exists(s.owner_user_id)
    )
  then
    update public.card_media_sessions set state='expired' where id=s.id;
  end if;
  return 'deleting';
end;
$function$

CREATE OR REPLACE FUNCTION public.create_client_card_atomic(p_owner_user_id uuid, p_card_allowance smallint, p_card_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  result public.cards%rowtype;
begin
  if p_owner_user_id is null or p_card_allowance is null or p_card_allowance not in (1, 3)
     or p_card_payload is null or jsonb_typeof(p_card_payload) <> 'object'
     or octet_length(p_card_payload::text) > 262144 then
    raise exception 'INVALID_CARD_CREATION_INPUT' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_object_keys(p_card_payload) as k(key)
    where key <> all(array['template_id', 'card_name', 'slug', 'full_name', 'title', 'first_name', 'last_name', 'job_title', 'company_name', 'email', 'phone', 'website', 'address', 'whatsapp', 'linkedin', 'instagram', 'facebook', 'youtube', 'booking_link', 'custom_url', 'profile_image_url', 'company_logo_url', 'selected_colour', 'selected_text_colour', 'field_order', 'field_visibility', 'custom_fields', 'action_config', 'lead_capture_settings', 'hidden_fields', 'status', 'is_published'])) then
    raise exception 'UNSUPPORTED_CARD_PAYLOAD_FIELD' using errcode = '22023';
  end if;
  if nullif(btrim(p_card_payload->>'card_name'), '') is null
     or nullif(btrim(p_card_payload->>'full_name'), '') is null
     or nullif(btrim(p_card_payload->>'slug'), '') is null
     or nullif(p_card_payload->>'template_id', '') is null
     or (p_card_payload->>'status') is null
     or (p_card_payload->>'status') not in ('published', 'draft')
     or jsonb_typeof(p_card_payload->'is_published') is distinct from 'boolean'
     or ((p_card_payload->>'is_published')::boolean is distinct from ((p_card_payload->>'status') = 'published')) then
    raise exception 'INVALID_CARD_PAYLOAD' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended('public.cards.card_slot:' || p_owner_user_id::text, 0)
  );
  if (select count(*) from public.cards where user_id = p_owner_user_id) >= p_card_allowance then
    raise exception 'CARD_ALLOWANCE_EXHAUSTED' using errcode = 'P0001';
  end if;
  -- Omit card_slot: assign_card_slot() reuses this transaction lock and allocates.
  -- No profile_id: it is absent from the verified live cards contract.
  insert into public.cards (user_id, template_id, card_name, slug, full_name, title, first_name, last_name, job_title, company_name, email, phone, website, address, whatsapp, linkedin, instagram, facebook, youtube, booking_link, custom_url, profile_image_url, company_logo_url, selected_colour, selected_text_colour, field_order, field_visibility, custom_fields, action_config, lead_capture_settings, hidden_fields, status, is_published)
  select p_owner_user_id, v.template_id, v.card_name, v.slug, v.full_name, v.title, v.first_name, v.last_name, v.job_title, v.company_name, v.email, v.phone, v.website, v.address, v.whatsapp, v.linkedin, v.instagram, v.facebook, v.youtube, v.booking_link, v.custom_url, v.profile_image_url, v.company_logo_url, v.selected_colour, v.selected_text_colour, v.field_order, v.field_visibility, v.custom_fields, v.action_config, v.lead_capture_settings, v.hidden_fields, v.status, v.is_published
  from jsonb_to_record(p_card_payload) as v(template_id uuid, card_name text, slug text, full_name text, title text, first_name text, last_name text, job_title text, company_name text, email text, phone text, website text, address text, whatsapp text, linkedin text, instagram text, facebook text, youtube text, booking_link text, custom_url text, profile_image_url text, company_logo_url text, selected_colour text, selected_text_colour text, field_order jsonb, field_visibility jsonb, custom_fields jsonb, action_config jsonb, lead_capture_settings jsonb, hidden_fields text[], status text, is_published boolean)
  returning * into result;
  return to_jsonb(result);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_client_card_media(p_owner uuid, p_session uuid, p_operation text, p_card_id uuid, p_allowance smallint, p_validated_payload jsonb, p_asset_receipts jsonb, p_expected_card_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  s public.card_media_sessions;
  a public.card_media_assets;
  original public.cards;
  saved public.cards;
  payload jsonb := p_validated_payload;
  digest text; revision text; result jsonb; intent jsonb;
  v_kind text; action text; old_ref text; next_ref text; aid uuid;
  old_refs jsonb := '{}'::jsonb;
  refs jsonb := '{}'::jsonb;
  new_ids uuid[] := array[]::uuid[];
  old_ids uuid[] := array[]::uuid[];
  involved uuid[];
  new_count integer := 0;
begin
  if p_owner is null or p_session is null or p_operation is null
     or p_operation not in ('create','edit') or p_allowance is null or p_allowance not in (1,3)
     or (p_operation='create' and (p_card_id is not null or p_expected_card_revision is not null))
     or (p_operation='edit' and (p_card_id is null or p_expected_card_revision is null
         or p_expected_card_revision !~ '^[0-9a-f]{64}$'))
     or payload is null or jsonb_typeof(payload)<>'object' or octet_length(payload::text)>262144
     or p_asset_receipts is null or jsonb_typeof(p_asset_receipts)<>'object'
     or octet_length(p_asset_receipts::text)>2048 then
    raise exception 'INVALID_MEDIA_FINALIZATION_INPUT' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(payload) k(key) where key <> all(array['template_id', 'card_name', 'slug', 'full_name', 'title', 'first_name', 'last_name', 'job_title', 'company_name', 'email', 'phone', 'website', 'address', 'whatsapp', 'linkedin', 'instagram', 'facebook', 'youtube', 'booking_link', 'custom_url', 'profile_image_url', 'company_logo_url', 'selected_colour', 'selected_text_colour', 'field_order', 'field_visibility', 'custom_fields', 'action_config', 'lead_capture_settings', 'hidden_fields', 'status', 'is_published']))
     or payload ?| array['profile_image_url','company_logo_url']
     or coalesce(payload->'custom_fields','{}'::jsonb) ? 'company_banner_url'
     or jsonb_typeof(payload->'custom_fields') is distinct from 'object'
     or jsonb_typeof(payload->'field_visibility') is distinct from 'object'
     or (p_operation='edit' and payload ? 'slug') then
    raise exception 'INVALID_FINALIZATION_PAYLOAD_FIELDS' using errcode='22023';
  end if;
  if nullif(btrim(payload->>'card_name'),'') is null
     or nullif(btrim(payload->>'full_name'),'') is null
     or nullif(payload->>'template_id','') is null
     or (p_operation='create' and nullif(btrim(payload->>'slug'),'') is null)
     or payload->>'status' is null or payload->>'status' not in ('draft','published')
     or jsonb_typeof(payload->'is_published') is distinct from 'boolean'
     or (payload->>'is_published')::boolean is distinct from (payload->>'status'='published') then
    raise exception 'INVALID_CARD_PAYLOAD' using errcode='22023';
  end if;
  if (select array_agg(key order by key) from jsonb_object_keys(p_asset_receipts) k(key))
     is distinct from array['banner','logo','profile'] then
    raise exception 'INVALID_MEDIA_INTENTS' using errcode='22023';
  end if;
  foreach v_kind in array array['profile','logo','banner'] loop
    intent := p_asset_receipts->v_kind;
    action := intent->>'operation';
    if jsonb_typeof(intent) is distinct from 'object' or action is null
       or action not in ('retain','remove','replace') then
      raise exception 'INVALID_MEDIA_INTENT' using errcode='22023';
    end if;
    if (action='replace' and (select array_agg(key order by key) from jsonb_object_keys(intent) k(key))
         is distinct from array['asset_id','operation'])
       or (action<>'replace' and intent <> jsonb_build_object('operation',action))
       or (action='retain' and p_operation='create') then
      raise exception 'INVALID_MEDIA_INTENT' using errcode='22023';
    end if;
    if action='replace' then
      aid := (intent->>'asset_id')::uuid;
      if aid is null or aid=any(new_ids) then raise exception 'INVALID_MEDIA_RECEIPT'; end if;
      new_ids := array_append(new_ids,aid);
    end if;
  end loop;
  -- Canonical JSONB digest v1: generated slug/allowance do not identify content.
  digest := encode(sha256(convert_to(jsonb_build_object('version',1,'operation',p_operation,
    'card_id',p_card_id,'payload',payload-'slug','media',p_asset_receipts,
    'expected_revision',p_expected_card_revision)::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended('public.cards.card_slot:' || p_owner::text,0));
  if not public.card_media_owner_exists(p_owner) then raise exception 'MEDIA_OWNER_UNAVAILABLE'; end if;

  -- Determine old bindings without locking the card ahead of its media sessions.
  if p_operation='edit' then
    select * into original from public.cards where id=p_card_id and user_id=p_owner;
    -- A deleted-card replay must still reach its durable session receipt.
    if found then
      old_refs := jsonb_build_object('profile',original.profile_image_url,'logo',original.company_logo_url,
        'banner',original.custom_fields->>'company_banner_url');
      foreach v_kind in array array['profile','logo','banner'] loop
        old_ref := old_refs->>v_kind;
        if old_ref like 'card-media:%' then
          old_ids := array_append(old_ids,substring(old_ref from 12)::uuid);
        end if;
      end loop;
    end if;
  end if;
  if exists(select 1 from public.card_media_assets x
      where x.id=any(new_ids) and x.session_id<>p_session)
     or exists(select 1 from public.card_media_assets x join public.card_media_sessions ms on ms.id=x.session_id
      where x.id=any(old_ids) and ms.owner_user_id<>p_owner) then
    raise exception 'MEDIA_RECEIPT_UNAVAILABLE';
  end if;
  select array_agg(distinct session_id) into involved from public.card_media_assets
    where id=any(new_ids || old_ids);
  perform 1 from public.card_media_sessions where id=p_session or id=any(involved) order by id for update;
  select * into s from public.card_media_sessions where id=p_session;
  if not found or s.owner_user_id is distinct from p_owner then raise exception 'MEDIA_SESSION_UNAVAILABLE'; end if;
  if s.finalization_digest is not null then
    if s.finalization_digest <> digest then raise exception 'MEDIA_IDEMPOTENCY_CONFLICT'; end if;
    return s.finalization_result || jsonb_build_object('replayed',true,'card_missing',
      not exists(select 1 from public.cards where id=s.finalized_card_id and user_id=p_owner));
  end if;
  if s.state<>'pending' or s.expires_at<=now()
     or s.template_id is distinct from (payload->>'template_id')::uuid
     or (p_operation='create' and s.card_id is not null)
     or (p_operation='edit' and s.card_id is distinct from p_card_id) then
    raise exception 'MEDIA_SESSION_UNAVAILABLE';
  end if;
  if p_operation='edit' then
    select * into original from public.cards where id=p_card_id and user_id=p_owner for update;
    if not found then raise exception 'MEDIA_CARD_UNAVAILABLE'; end if;
    revision := encode(sha256(convert_to(to_jsonb(original)::text,'UTF8')),'hex');
    if revision <> p_expected_card_revision then raise exception 'CARD_REVISION_CONFLICT'; end if;
    -- Recheck the pre-lock snapshot; never continue with an incomplete lock set.
    if old_refs is distinct from jsonb_build_object('profile',original.profile_image_url,
      'logo',original.company_logo_url,'banner',original.custom_fields->>'company_banner_url') then
      raise exception 'CARD_REVISION_CONFLICT';
    end if;
  end if;
  -- Include all new-session assets: attach_card_media_session visits them all.
  perform 1 from public.card_media_assets
    where session_id=p_session or id=any(old_ids || new_ids) order by id for update;
  foreach v_kind in array array['profile','logo','banner'] loop
    action := p_asset_receipts->v_kind->>'operation';
    old_ref := old_refs->>v_kind;
    if action='replace' then
      aid := (p_asset_receipts->v_kind->>'asset_id')::uuid;
      select * into a from public.card_media_assets where id=aid;
      if not found or a.session_id<>p_session or a.kind<>v_kind or a.state<>'ready' then
        raise exception 'MEDIA_RECEIPT_UNAVAILABLE';
      end if;
      next_ref := 'card-media:' || aid::text;
      new_count := new_count+1;
    elsif action='retain' then
      next_ref := coalesce(old_ref,'');
      if next_ref like 'card-media:%' then
        aid := substring(next_ref from 12)::uuid;
        if not exists(select 1 from public.card_media_assets x join public.card_media_sessions ms on ms.id=x.session_id
          where x.id=aid and x.kind=v_kind and x.state='attached' and ms.owner_user_id=p_owner and ms.card_id=p_card_id
          and ms.state='attached') then raise exception 'MEDIA_RETAINED_ASSET_UNAVAILABLE'; end if;
      end if;
      -- Legacy data/http media copied ONLY from the exact owned card, not input.
    else
      next_ref := '';
    end if;
    refs := refs || jsonb_build_object(v_kind,next_ref);
  end loop;
  payload := payload || jsonb_build_object('profile_image_url',refs->>'profile','company_logo_url',refs->>'logo',
    'custom_fields',(payload->'custom_fields') || jsonb_build_object('company_banner_url',refs->>'banner'));
  if octet_length(payload::text)>262144 then raise exception 'INVALID_CARD_PAYLOAD'; end if;
  if p_operation='create' then
    result := public.create_client_card_atomic(p_owner,p_allowance,payload);
    select * into saved from public.cards where id=(result->>'id')::uuid;
  else
    -- Exact validated content update; immutable owner/id/slug/slot never assigned.
    update public.cards c set
    template_id=v.template_id,
    card_name=v.card_name,
    full_name=v.full_name,
    title=v.title,
    first_name=v.first_name,
    last_name=v.last_name,
    job_title=v.job_title,
    company_name=v.company_name,
    email=v.email,
    phone=v.phone,
    website=v.website,
    address=v.address,
    whatsapp=v.whatsapp,
    linkedin=v.linkedin,
    instagram=v.instagram,
    facebook=v.facebook,
    youtube=v.youtube,
    booking_link=v.booking_link,
    custom_url=v.custom_url,
    profile_image_url=v.profile_image_url,
    company_logo_url=v.company_logo_url,
    selected_colour=v.selected_colour,
    selected_text_colour=v.selected_text_colour,
    field_order=v.field_order,
    field_visibility=v.field_visibility,
    custom_fields=v.custom_fields,
    action_config=v.action_config,
    lead_capture_settings=v.lead_capture_settings,
    hidden_fields=v.hidden_fields,
    status=v.status,
    is_published=v.is_published
    from jsonb_to_record(payload) as v(template_id uuid, card_name text, slug text, full_name text, title text, first_name text, last_name text, job_title text, company_name text, email text, phone text, website text, address text, whatsapp text, linkedin text, instagram text, facebook text, youtube text, booking_link text, custom_url text, profile_image_url text, company_logo_url text, selected_colour text, selected_text_colour text, field_order jsonb, field_visibility jsonb, custom_fields jsonb, action_config jsonb, lead_capture_settings jsonb, hidden_fields text[], status text, is_published boolean)
    where c.id=p_card_id and c.user_id=p_owner returning c.* into saved;
  end if;
  if new_count>0 then
    perform public.attach_card_media_session(p_owner,p_session,saved.id);
  else
    -- Zero new media / removal-only saves also consume their retry session.
    update public.card_media_sessions set state='attached',card_id=saved.id where id=p_session;
  end if;
  -- Persisted replacement is now in the SAME transaction. Never delete objects here.
  foreach aid in array old_ids loop
    -- Never retire a foreign/corrupt binding; retained bindings were checked above.
    if exists(select 1 from public.card_media_assets x join public.card_media_sessions ms on ms.id=x.session_id
      where x.id=aid and ms.owner_user_id=p_owner and ms.card_id=saved.id) then
      perform public.retire_card_media_asset(aid);
    end if;
  end loop;
  revision := encode(sha256(convert_to(to_jsonb(saved)::text,'UTF8')),'hex');
  result := jsonb_build_object('card_id',saved.id,'status',saved.status,'is_published',saved.is_published,
    'revision',revision,'replayed',false,'card_missing',false);
  update public.card_media_sessions set finalization_digest=digest,finalized_operation=p_operation,
    finalized_card_id=saved.id,finalization_result=result,finalized_at=now() where id=p_session;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_client_card_edit_snapshot(p_owner uuid, p_card_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  card_row public.cards%rowtype;
  result jsonb;
begin
  select c.* into card_row
  from public.cards as c
  where c.id = p_card_id and c.user_id = p_owner;

  -- Identical result for a missing card, foreign-owned card or null identity.
  if not found then
    return null;
  end if;

  result := jsonb_build_object(
    'card', to_jsonb(card_row),
    'revision', encode(sha256(convert_to(to_jsonb(card_row)::text,'UTF8')),'hex')
  );

  -- Bounded full snapshot, with room for legacy inline media. Never truncate:
  -- the revision must describe exactly the complete card returned to the editor.
  -- This response ceiling does not change any write/upload/field validation limit.
  if octet_length(result::text) > 16777216 then
    raise exception 'CARD_EDIT_SNAPSHOT_TOO_LARGE' using errcode = '54000';
  end if;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_current_client_account_status()
 RETURNS TABLE(client_id uuid, client_status text, client_user_id uuid, client_user_status text, is_suspended boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid;
  current_email text;
  selected_client_id uuid;
  selected_client_status text;
  selected_client_user_id uuid;
  selected_client_user_status text;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'Authentication required'
      using errcode = '28000';
  end if;

  select users.email
  into current_email
  from auth.users as users
  where users.id = current_user_id;

  select clients.id, clients.status
  into selected_client_id, selected_client_status
  from public.clients
  where clients.profile_id = current_user_id
     or clients.user_id = current_user_id
     or (
       current_email is not null
       and lower(coalesce(clients.email, '')) = lower(current_email)
     )
  order by
    case
      when clients.profile_id = current_user_id or clients.user_id = current_user_id then 0
      else 1
    end,
    clients.created_at asc
  limit 1;

  select client_users.id, client_users.status
  into selected_client_user_id, selected_client_user_status
  from public.client_users
  where client_users.profile_id = current_user_id
     or client_users.user_id = current_user_id
     or (
       selected_client_id is not null
       and client_users.client_id = selected_client_id
       and current_email is not null
       and lower(coalesce(client_users.email, '')) = lower(current_email)
     )
     or (
       current_email is not null
       and lower(coalesce(client_users.email, '')) = lower(current_email)
     )
  order by
    case
      when client_users.profile_id = current_user_id or client_users.user_id = current_user_id then 0
      else 1
    end,
    client_users.created_at asc
  limit 1;

  client_id := selected_client_id;
  client_status := coalesce(selected_client_status, 'active');
  client_user_id := selected_client_user_id;
  client_user_status := coalesce(selected_client_user_status, 'active');
  is_suspended :=
    lower(coalesce(selected_client_status, 'active')) in ('suspended', 'inactive')
    or lower(coalesce(selected_client_user_status, 'active')) in ('suspended', 'inactive');

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_card_media_cleanup(p_asset uuid, p_action text, p_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.card_media_assets%rowtype; s public.card_media_sessions%rowtype;
  owner_id uuid; session_id uuid; outcome text; ref text; token uuid;
begin
  perform public.check_card_media_cleanup_boundary();
  if p_action is null or p_action not in ('claim','check','complete','retry') then raise exception 'MEDIA_CLEANUP_ACTION_INVALID'; end if;
  select ms.owner_user_id,ms.id into owner_id,session_id from public.card_media_assets ma
    join public.card_media_sessions ms on ms.id=ma.session_id where ma.id=p_asset;
  if not found then return jsonb_build_object('status','invalid'); end if;
  perform pg_advisory_xact_lock(hashtextextended('public.cards.card_slot:'||owner_id::text,0));
  select * into s from public.card_media_sessions where id=session_id for update;
  select * into a from public.card_media_assets where id=p_asset for update;
  if not found then return jsonb_build_object('status','invalid'); end if;
  if p_action <> 'claim' and (p_token is null or a.cleanup_token is distinct from p_token
    or a.cleanup_lease_until <= clock_timestamp() or a.cleanup_lease_until is null) then
    return jsonb_build_object('status','stale');
  end if;
  if p_action='claim' and a.cleanup_lease_until > clock_timestamp() then
    return jsonb_build_object('status','busy');
  end if;
  ref := 'card-media:'||a.id::text;
  -- GLOBAL references: never rely only on the owning card/session or visibility.
  if exists(select 1 from public.cards where profile_image_url=ref or company_logo_url=ref
    or custom_fields->>'company_banner_url'=ref) then
    update public.card_media_assets set cleanup_after=now()+interval '24 hours',
      cleanup_token=null,cleanup_lease_until=null where id=a.id;
    return jsonb_build_object('status','referenced');
  end if;
  if p_action='claim' then
    if a.cleanup_after > now() then return jsonb_build_object('status','not_due'); end if;
    if a.state='attached' then
      -- Deleted-card/account or superseded orphan. Retirement starts the SAME 24h grace.
      outcome := public.retire_card_media_asset(a.id);
      return jsonb_build_object('status',outcome);
    end if;
    if a.state in ('reserved','ready') and s.state='pending' and s.expires_at > now()
      and public.card_media_owner_exists(s.owner_user_id) then
      update public.card_media_assets set cleanup_after=s.expires_at where id=a.id;
      return jsonb_build_object('status','not_due');
    end if;
    if a.state <> 'deleted' then
      outcome := public.claim_card_media_cleanup(a.id);
      if outcome <> 'deleting' then return jsonb_build_object('status',outcome); end if;
    end if;
    token := gen_random_uuid();
    update public.card_media_assets set cleanup_token=token,
      cleanup_lease_until=clock_timestamp()+interval '5 minutes',cleanup_attempts=cleanup_attempts+1 where id=a.id;
    return jsonb_build_object('status','claimed','token',token,'retried',a.cleanup_attempts>0,
      'path',s.owner_user_id::text||'/'||s.id::text||'/'||a.kind||'/'||a.id::text||
        case a.mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png' when 'image/webp' then '.webp' end);
  end if;
  if a.state not in ('deleting','deleted') then return jsonb_build_object('status','invalid'); end if;
  if p_action='check' then return jsonb_build_object('status','authorized'); end if;
  if p_action='complete' then
    -- Caller has confirmed Storage absence. Retain tombstone AND receipt forever.
    -- Reconcile tombstones daily to catch a very late in-flight abandoned upload.
    update public.card_media_assets set state='deleted',cleanup_token=null,cleanup_lease_until=null,
      cleanup_after=now()+interval '24 hours' where id=a.id;
    return jsonb_build_object('status','deleted');
  end if;
  update public.card_media_assets set cleanup_token=null,cleanup_lease_until=null,
    cleanup_after=now()+interval '15 minutes' where id=a.id;
  return jsonb_build_object('status','retry');
end $function$

CREATE OR REPLACE FUNCTION public.mark_card_media_ready(p_owner uuid, p_session uuid, p_asset uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare s public.card_media_sessions;
begin
  select * into s from public.card_media_sessions where id=p_session for update;
  if not found or s.owner_user_id is distinct from p_owner or s.state <> 'pending' or s.expires_at <= now()
     or not public.card_media_owner_exists(p_owner) then
    raise exception 'MEDIA_SESSION_UNAVAILABLE';
  end if;
  update public.card_media_assets set state='ready'
    where id=p_asset and session_id=p_session and state in ('reserved','ready');
  if not found then raise exception 'MEDIA_ASSET_UNAVAILABLE'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.prune_empty_card_media_sessions(p_limit integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare s record; removed integer := 0;
begin
  perform public.check_card_media_cleanup_boundary();
  if p_limit is null or p_limit < 1 or p_limit > 50 then raise exception 'MEDIA_CLEANUP_BATCH_INVALID'; end if;
  for s in select id from public.card_media_sessions ms
    where ms.state in ('pending','expired') and ms.expires_at < now()-interval '7 days'
      and ms.finalization_digest is null and ms.finalization_result is null and ms.finalized_at is null
      and not exists(select 1 from public.card_media_assets a where a.session_id=ms.id)
    order by ms.expires_at,ms.id limit p_limit for update of ms skip locked loop
    -- Reserve/finalize both acquire the session lock first; expired sessions cannot revive.
    delete from public.card_media_sessions where id=s.id;
    removed := removed+1;
  end loop;
  return removed;
end $function$

CREATE OR REPLACE FUNCTION public.reserve_card_media_asset(p_owner uuid, p_session uuid, p_kind text, p_sha256 text, p_mime text, p_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare s public.card_media_sessions; a public.card_media_assets; ext text;
begin
  select * into s from public.card_media_sessions where id = p_session for update;
  if not found or s.owner_user_id is distinct from p_owner or s.state <> 'pending' or s.expires_at <= now()
     or not public.card_media_owner_exists(p_owner) then
    raise exception 'MEDIA_SESSION_UNAVAILABLE';
  end if;
  if not exists(select 1 from public.card_media_assets where session_id=p_session and kind=p_kind and sha256=p_sha256)
     and (select count(*) from public.card_media_assets where session_id=p_session) >= 12 then
    raise exception 'MEDIA_SESSION_ASSET_LIMIT';
  end if;
  insert into public.card_media_assets(session_id,kind,sha256,mime_type,size_bytes,cleanup_after)
    values(p_session,p_kind,p_sha256,p_mime,p_size,s.expires_at)
    on conflict(session_id,kind,sha256) do nothing;
  select * into a from public.card_media_assets
    where session_id=p_session and kind=p_kind and sha256=p_sha256 for update;
  if a.state not in ('reserved','ready') or a.mime_type is distinct from p_mime or a.size_bytes is distinct from p_size then
    raise exception 'MEDIA_RETRY_CONFLICT';
  end if;
  ext := case a.mime_type when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end;
  return jsonb_build_object('asset_id',a.id,'state',a.state,'object_path',
    s.owner_user_id::text || '/' || s.id::text || '/' || a.kind || '/' || a.id::text || '.' || ext);
end;
$function$

CREATE OR REPLACE FUNCTION public.retire_card_media_asset(p_asset uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare sid uuid; owner_id uuid; a public.card_media_assets; ref text;
begin
  select session_id into sid from public.card_media_assets where id=p_asset;
  if not found then return 'not_found'; end if;
  select owner_user_id into owner_id from public.card_media_sessions where id=sid;
  perform pg_advisory_xact_lock(hashtextextended('public.cards.card_slot:' || owner_id::text,0));
  perform 1 from public.card_media_sessions where id=sid for update;
  select * into a from public.card_media_assets where id=p_asset for update;
  if a.state <> 'attached' then return a.state; end if;
  ref := 'card-media:' || a.id::text;
  if exists(select 1 from public.cards where profile_image_url=ref or company_logo_url=ref
      or custom_fields->>'company_banner_url'=ref) then return 'referenced'; end if;
  update public.card_media_assets set state='cleanup_pending',cleanup_after=now()+interval '24 hours' where id=p_asset;
  return 'cleanup_pending';
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
